import java.io.IOException;

public class codeforce {

    private static int nextInt() throws IOException {
        int c;
        do {
            c = System.in.read();
        } while (c <= ' ');

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = System.in.read();
        }

        int number = 0;
        while (c >= '0' && c <= '9') {
            number = number * 10 + (c - '0');
            c = System.in.read();
        }
        return number * sign;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[3];
        int[] b = new int[3];

        for (int i = 0; i < 3; i++) {
            a[i] = nextInt();
        }
        for (int i = 0; i < 3; i++) {
            b[i] = nextInt();
        }

        int max = 0;
        int min = 0;

        for (int i = 0; i < 3; i++) {
            max += a[i] < b[(i + 1) % 3] ? a[i] : b[(i + 1) % 3];

            int left = a[i] - b[i] - b[(i + 2) % 3];
            if (left > 0) {
                min += left;
            }
        }

        System.out.println(min + " " + max);
    }
}
